package dev.patienty.assistant;
import dev.patienty.assistant.AssistantContext.ContextItem;import dev.patienty.patient.PatientDtos.*;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Component;
@Component
public class RuleBasedAiAnswerGenerator implements AiAnswerGenerator {public GeneratedAnswer generate(String q,AssistantIntent intent,AssistantContext context,PatientSummary summary){return switch(intent){case RECENT_CHANGES->summary.observations().isEmpty()?list(context,"최근 기록에서 두드러진 변화가 확인되지 않았습니다.","NO_NOTABLE_CHANGE"):new GeneratedAnswer(summary.text(),summary.observations());case RECENT_EXAMINATIONS->list(context,"최근 검사 기록을 정리했습니다.","RECENT_EXAMINATIONS");case MEDICATION_CHANGES->medication(context,summary);case MEASUREMENT_TREND->trend(context,summary);case ENCOUNTER_TIMELINE->list(context,"최근 진료 이력을 시간순으로 정리했습니다.","ENCOUNTER_TIMELINE");case UNSUPPORTED->throw new IllegalArgumentException("Unsupported intent");};}
    private static GeneratedAnswer medication(AssistantContext c,PatientSummary s){List<Observation>o=s.observations().stream().filter(x->"MEDICATION_CHANGE".equals(x.type())).toList();return o.isEmpty()?list(c,"확인 가능한 처방 기록에서 변경 사항이 발견되지 않았습니다.","NO_NOTABLE_CHANGE"):new GeneratedAnswer("최근 두 처방 사이의 변경 사항을 확인했습니다.",o);}
    private static GeneratedAnswer trend(AssistantContext c,PatientSummary s){Set<String>ids=new HashSet<>();c.items().forEach(i->ids.add(i.evidenceId()));List<Observation>o=s.observations().stream().filter(x->x.type().startsWith("MEASUREMENT")||"ABNORMAL_RESULT".equals(x.type())).filter(x->ids.containsAll(x.evidenceIds())).toList();return o.isEmpty()?list(c,"측정값은 있지만 뚜렷한 추세를 계산할 만큼 변화가 크지 않습니다.","NO_NOTABLE_CHANGE"):new GeneratedAnswer("요청한 측정값의 최근 변화를 확인했습니다.",o);}
    private static GeneratedAnswer list(AssistantContext c,String answer,String type){List<String>ids=c.items().stream().limit(5).map(ContextItem::evidenceId).toList();return new GeneratedAnswer(answer,ids.isEmpty()?List.of():List.of(new Observation(type,"INFORMATION",answer,ids)));}}
